`;function Dp(e,t,n,r){const o=e.filter(h=>h.category==="lighting"&&h.type!=="hazer").sort((h,f)=>(h.channel||999)-(f.channel||999)),i=e.filter(h=>h.type==="batten"),s=new Date().toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric"}),a=o.map(h=>{var $;const f=i.find(x=>x.id===h.battenId),m=sn.find(x=>x.code===h.gelCode)||{code:"Open",name:"Open White",hex:"#ffffff"},S=((h.x||0)/B).toFixed(1),k=((h.y||0)/B).toFixed(1);return`
